plugins {
    alias(libs.plugins.kotlin.jvm)
    alias(libs.plugins.compose.multiplatform)
    alias(libs.plugins.compose.compiler)
}

dependencies {
    implementation(project(":sample:common"))
    implementation(compose.desktop.currentOs)
}

compose.desktop {
    application {
        mainClass = "com.coderwise.libs.sample.desktop.MainKt"

        nativeDistributions {
            packageName = "Coderwise Libraries"
            packageVersion = "1.0.0"

            // Generated by sample/icon/generate.py.
            macOS { iconFile.set(project.file("icons/icon.icns")) }
            windows { iconFile.set(project.file("icons/icon.ico")) }
            linux { iconFile.set(project.file("icons/icon.png")) }
        }
    }
}

// A packaged app is a bundle, so macOS names it and draws its icon from the bundle. A Gradle run
// is the bare `java` binary: the app menu says MainKt (the main class), the Dock tooltip says
// java, and the Dock shows Java's icon -- until the JVM is told otherwise at launch. These
// options exist only on macOS (any other JVM refuses to start on them), and only the run task
// gets them, because the icon path is this machine's and must not be baked into a package.
if (System.getProperty("os.name").startsWith("Mac")) {
    // The compose plugin registers `run` after this script is evaluated, hence the lazy match.
    tasks.withType<JavaExec>().matching { it.name == "run" }.configureEach {
        jvmArgs(
            "-Xdock:name=Coderwise Libraries",
            "-Xdock:icon=${file("icons/icon.icns")}"
        )
    }
}
